pub mod token_h;

use std::{
    io::Write,
    path::Path,
    process::{Command, Stdio},
};

const HEADER: &str =
    "// This file is generated by maf-generator. Do not edit this file manually.\n";

pub fn save_c_file<P: AsRef<Path>, T: askama::Template>(path: P, tmpl: T) -> anyhow::Result<()> {
    let content = tmpl.render()?;

    let mut clang_format = Command::new("clang-format")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()?;

    {
        let mut stdin = clang_format.stdin.take().expect("no stdin handle");
        let code = &format!("{header}{content}\n", header = HEADER, content = content);
        write!(stdin, "{code}")?;
    }

    let output = clang_format.wait_with_output()?;
    std::fs::write(path, output.stdout)?;

    Ok(())
}
